import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TarUtils.parseOctal
 */
public class TarUtils_parseOctal_TriageGen2Test {





    @Test
    public void testParseOctal_WithTrailingSpacesAndNulls() {
        // Note: buffer[end-1] logic depends on the byte being 0 or ' '
        byte[] buffer = "000123  \0\0".getBytes();
        // Manual construction to ensure NUL bytes are present
        byte[] customBuffer = new byte[10];
        System.arraycopy("000123  ".getBytes(), 0, customBuffer, 0, 8);
        customBuffer[8] = 0;
        customBuffer[9] = 0;

        assertEquals(83L, TarUtils.parseOctal(customBuffer, 0, 10));
    }














}

